import re

_VERSION = re.compile(r"(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)")

# Header: type, optional (scope), optional !, then ": " and non-empty text
# that does not start with a space. Scope is anything but parentheses, non-empty.
_HEADER = re.compile(r"([a-z]+)(?:\(([^()]+)\))?(!)?: (?! )(.+)")

_BREAKING_LINE = ("BREAKING CHANGE: ", "BREAKING-CHANGE: ")


def _parse_version(current):
    if not isinstance(current, str):
        raise ValueError("invalid version: %r" % (current,))
    m = _VERSION.fullmatch(current)
    if m is None:
        raise ValueError("invalid version: %r" % (current,))
    return tuple(int(part) for part in m.groups())


def _classify(message):
    """Return 'breaking', 'feature', 'fix', 'other', or None if the header does not count."""
    lines = message.split("\n")
    m = _HEADER.fullmatch(lines[0])
    if m is None:
        return None
    ctype, _scope, bang, _text = m.groups()
    breaking = bool(bang) or any(
        line.startswith(prefix) for line in lines[1:] for prefix in _BREAKING_LINE
    )
    if breaking:
        return "breaking"
    if ctype == "feat":
        return "feature"
    if ctype == "fix":
        return "fix"
    return "other"


def next_version(current, commits):
    """The version after `current`, decided by the commit messages. See TASK.md."""
    major, minor, patch = _parse_version(current)

    kinds = {_classify(message) for message in commits}
    kinds.discard(None)

    if "breaking" in kinds:
        if major >= 1:
            return "%d.0.0" % (major + 1)
        return "0.%d.0" % (minor + 1)

    if "feature" in kinds:
        if major >= 1:
            return "%d.%d.0" % (major, minor + 1)
        return "0.%d.%d" % (minor, patch + 1)

    if "fix" in kinds:
        return "%d.%d.%d" % (major, minor, patch + 1)

    return current
